import json, subprocess, sys, random, string

rng=random.Random(42)
def rname():
    nl=rng.randint(0,3)
    if nl==0: return "."
    labels=[]
    for _ in range(nl):
        style=rng.random()
        if style<0.2: labels.append("*")
        else: labels.append(''.join(rng.choice(string.ascii_letters+string.digits+'-_') for _ in range(rng.randint(1,6))))
    return '.'.join(labels)+'.'
def rdata(t):
    if t=='A': return '.'.join(str(rng.randint(0,255)) for _ in range(4))
    if t=='AAAA': return rng.choice(['::1','2001:DB8::1','::ffff:1.2.3.4','fe80::1'])
    if t=='TXT': return ''.join(rng.choice(' abcXYZ019!') for _ in range(rng.randint(0,10)))
    if t=='CNAME': return rname()
def gen():
    zones=[]
    for _ in range(rng.randint(0,4)):
        origin=rname()
        recs=[]
        for _ in range(rng.randint(0,5)):
            # owner at or below origin: mostly prepend label
            owner=origin
            if origin!='.' and rng.random()<0.6:
                owner='x.'+origin
            t=rng.choice(['A','AAAA','TXT','CNAME'])
            recs.append({'owner':owner,'type':t,'data':rdata(t)})
        zones.append({'origin':origin,'records':recs})
    # dedupe origins
    seen=set(); z2=[]
    for z in zones:
        o=z['origin'].lower()
        if o in seen: continue
        seen.add(o); z2.append(z)
    profiles=[{'id':f'p{i}','max_aliases':rng.randint(0,8),'cname':rng.choice(['follow','stop']),'wildcard':rng.choice(['rfc','off','one-label'])} for i in range(rng.randint(1,5))]
    queries=[{'id':f'q{i}','name':rname(),'type':rng.choice(['A','AAAA','TXT','CNAME']),'cost':rng.randint(1,50)} for i in range(rng.randint(0,8))]
    obs=[]
    for i in range(rng.randint(0,6)):
        if not queries: break
        q=rng.choice(queries); p=rng.choice(profiles)
        if rng.random()<0.3:
            res={'status':'timeout'}
        else:
            ans=[]
            for _ in range(rng.randint(0,4)):
                t=rng.choice(['A','AAAA','TXT','CNAME'])
                ans.append({'owner':rname(),'type':t,'data':rdata(t)})
            res={'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
        obs.append({'id':f'o{i}','query':q['id'],'profile':p['id'],'result':res})
    return {'zones':z2,'profiles':profiles,'queries':queries,'observations':obs}

for it in range(400):
    doc=gen()
    p=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(doc).encode(),capture_output=True)
    if p.returncode!=0:
        print("CRASH",it,p.stderr.decode()[:500]); print(json.dumps(doc)); break
    try:
        out=json.loads(p.stdout)
    except Exception as e:
        print("BADOUT",it,e,p.stdout[:200]); break
    if 'error' in out:
        print("UNEXPECTED INVALID",it); print(json.dumps(doc)); break
    # basic structural checks
    assert set(out)=={'runs','audits','diagnostic'}
    # count runs
    assert len(out['runs'])==len(doc['queries'])*len(doc['profiles'])
else:
    print("valid fuzz OK")
